import { NextRequest } from 'next/server';
import { TABLE_REGISTRY } from '@/lib/tableRegistry';
import { dataGet, dataPost, dataPatch, dataDelete, dataNotFound } from '@/lib/dataRoute';

/* Cms domain data route (GENERATED by the wire closure, 2026-11-15):
   the named API surface for the cms tables that had no hand-written
   route. Tenant-scoped CRUD through the shared handler in
   lib/dataRoute.ts, driven by each table's TABLE_REGISTRY entry.
   Tables served here:
   - cms_audience_segments
   - cms_audit_log
   - cms_block_schemas
   - cms_bundle_rules
   - cms_campaigns
   - cms_cart_thresholds
   - cms_cdn_profiles
   - cms_component_analytics
   - cms_design_tokens
   - cms_fallback_pages
   - cms_funnel_events
   - cms_galleries
   - cms_gallery_items
   - cms_global_content
   - cms_global_copy
   - cms_integrations
   - cms_locales
   - cms_media_assets
   - cms_media_taxonomy
   - cms_offers
   - cms_policy_acceptances
   - cms_versions
   - cms_volume_tiers
   - cms_website_settings
*/

const SERVED = new Set([
  'cms_audience_segments',
  'cms_audit_log',
  'cms_block_schemas',
  'cms_bundle_rules',
  'cms_campaigns',
  'cms_cart_thresholds',
  'cms_cdn_profiles',
  'cms_component_analytics',
  'cms_design_tokens',
  'cms_fallback_pages',
  'cms_funnel_events',
  'cms_galleries',
  'cms_gallery_items',
  'cms_global_content',
  'cms_global_copy',
  'cms_integrations',
  'cms_locales',
  'cms_media_assets',
  'cms_media_taxonomy',
  'cms_offers',
  'cms_policy_acceptances',
  'cms_versions',
  'cms_volume_tiers',
  'cms_website_settings'
]);

function entry(table: string) {
  return SERVED.has(table) ? TABLE_REGISTRY[table] ?? null : null;
}

export async function GET(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataGet(req, table, r) : dataNotFound(table);
}

export async function POST(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPost(req, table, r) : dataNotFound(table);
}

export async function PATCH(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataPatch(req, table, r) : dataNotFound(table);
}

export async function DELETE(req: NextRequest, ctx: { params: Promise<{ table: string }> }) {
  const { table } = await ctx.params;
  const r = entry(table);
  return r ? dataDelete(req, table, r) : dataNotFound(table);
}
